<script setup lang="ts">
import {ref} from 'vue';
import {useAccountingSuperAdmin} from './permissions';
import {useAccountingAlerts} from './useAccountingAlerts';
import AdminDialog from '../../AdminDialog.vue';
const props=defineProps<{company:number;type:string;record:any;csrf?:string;allowEdit?:boolean}>();
const emit=defineEmits(['changed','notice']);const superAdmin=useAccountingSuperAdmin();
const action=ref(''),reason=ref(''),date=ref(new Date().toLocaleDateString('en-CA')),busy=ref(false),error=ref('');useAccountingAlerts(error);
function open(value:string){action.value=value;reason.value='';error.value='';date.value=new Date().toLocaleDateString('en-CA');}
async function apply(){if(busy.value)return;busy.value=true;error.value='';try{
 const r=await fetch('/accounting/api/admin-records/'+props.type+'/'+props.record.id,{method:'POST',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:JSON.stringify({company_id:props.company,version:props.record.version||1,action:action.value,reason:reason.value,posting_date:date.value})});
 const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message||'Unable to manage this record.');
 const completed=action.value;action.value='';emit('notice',d.message);emit('changed',{...d,action:completed});
}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><div v-if="superAdmin&&record?.id" class="ac-admin-record-actions"><span class="muted">Super Admin controls</span><button v-if="allowEdit" type="button" class="button" @click="open('edit')">Edit record</button><button v-if="!record.archived" type="button" class="button ac-danger" @click="open('delete')">{{type==='account'?'Delete account':'Delete record'}}</button><button v-else type="button" class="button" @click="open('restore')">Restore account</button>
<AdminDialog v-if="action" :title="action==='restore'?'Restore account':action==='edit'?'Edit accounting record':'Delete accounting record'" @close="!busy&&(action='')"><form @submit.prevent="apply"><p v-if="record.status==='posted'" class="ac-help">The posted amount will be offset by a reversal. {{action==='edit'?'A replacement draft will open for correction.':'The original stays in audit history and is removed from active records.'}}</p><p v-else-if="type==='account'" class="ac-help">{{action==='restore'?'Restore this account and its archived children.':'Remove this account and all children from the active chart and new-entry selections. Posted ledger history and amounts are retained.'}}</p><p v-else-if="type==='cheque'" class="ac-help">{{action==='edit'?'Review the correction form. Any cleared payment is reversed only when you save the correction.':'Any cleared payment will be reversed and the invoice outstanding restored. The original cheque stays in audit history.'}}</p><p v-else-if="type==='order'" class="ac-help">{{action==='edit'?'Review the replacement form. The old order changes only when the replacement saves successfully.':'Both order sides and linked invoices will be removed from active records. Active payments and cheques must be resolved first.'}}</p><p v-else class="ac-help">The previous saved record and the reason will remain in audit history.</p><label v-if="record.status==='posted'">Correction date<input v-model="date" type="date" required :min="record.posting_date" :max="new Date().toLocaleDateString('en-CA')" :disabled="busy"></label><label>Reason<textarea v-model="reason" required minlength="5" maxlength="2000" rows="3" :disabled="busy" placeholder="Explain this correction or removal"></textarea></label><div class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="action=''">Cancel</button><button class="button" :class="action==='delete'?'ac-danger':'primary'" :disabled="busy||reason.trim().length<5">{{busy?'Processing...':action==='restore'?'Restore account':action==='edit'?'Continue to edit':'Confirm deletion'}}</button></div></form></AdminDialog></div></template>
<style scoped>.ac-admin-record-actions{display:flex;align-items:center;flex-wrap:wrap;gap:8px;padding:16px 0;border-top:1px solid var(--border,#333);margin-top:16px}.ac-admin-record-actions>span{margin-right:auto}</style>
